-- ============================================================================
-- LOCAL ONLY. Seeds a Player Pick'em league for NCAAFB 2026 week 5 (completed),
-- with members, rosters and (fake) scores, for leaderboard testing.
--
-- Run against the LOCAL API database (pgAdmin / psql). Re-runnable: it deletes
-- its own previous seed first (fixed league id 5eed0005-0000-4000-8000-00000000a001).
--
-- Rosters are real week-5 athletes from the local API's athlete feed (ND @ UNC
-- included); points and stat lines are made up. Generated by Claude Code.
--   roster 1: QB Carr 23.9, RB1 Williams 10.5, RB2 Riley 5.6, WR1 Faison 13.4, WR2 Smith 14.1, TE Thurman 10.1, FLEX Baugh 14.9, K Porath 2.7  = 95.2
--   roster 2: QB Maiava 24.5, RB1 Roberts 22.7, RB2 Richard 14.8, WR1 Toney 17.9, WR2 Hernandez 15.0, TE Reynolds 8.1, FLEX Bishop 7.8, K Armstrong 6.4  = 117.2
--   roster 3: QB Jennings 12.8, RB1 Beebe Jr. 20.7, RB2 Cook 10.0, WR1 Evans III 10.0, WR2 Lee 22.6, TE Overmyer 1.8, FLEX Freeman 21.6, K Hauser 9.7  = 109.2
--   roster 4: QB Sayin 13.6, RB1 Pettaway 15.0, RB2 Miller 12.1, WR1 Becker 4.7, WR2 Buchanan 8.7, TE Skinner 3.6, FLEX Olugbode 7.2, K Suarez 14.8  = 79.7
--   roster 5: QB Taylor 21.3, RB1 Overton Jr. 12.6, RB2 Jones 9.7, WR1 Gilmer 21.4, WR2 Coleman-Williams 1.8, TE Harris 11.2, FLEX Raphael 8.0, K Calvert 13.3  = 99.3
--   roster 6: QB Grunkemeyer 27.4, RB1 Bothwell 14.5, RB2 Williams 20.6, WR1 Dixon-Wyatt 24.4, WR2 Brown 14.2, TE Green 9.6, FLEX Payne 8.5, K Klein 3.2  = 122.4
-- ============================================================================
BEGIN;

--select * from public."User" order by "DisplayName";

-- ── 1. EDIT ME: members by email, in order. ord 1 is the commissioner.
--    Up to 6 members get a roster (member N gets roster N).
CREATE TEMP TABLE seed_member (ord int PRIMARY KEY, email text NOT NULL) ON COMMIT DROP;
INSERT INTO seed_member (ord, email) VALUES
  (1, 'foo@bar.com'),
  (2, 'jrandallsexton@gmail.com'),
  (3, 'jeff.l.hogg@gmail.com');

-- ── 2. Resolve members; stop on any unknown email.
CREATE TEMP TABLE seed_user ON COMMIT DROP AS
SELECT m.ord, u."Id" AS user_id
FROM seed_member m
LEFT JOIN "User" u ON lower(u."Email") = lower(m.email);

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM seed_user WHERE user_id IS NULL) THEN
    RAISE EXCEPTION 'Unknown member email(s): %',
      (SELECT string_agg(m.email, ', ') FROM seed_member m JOIN seed_user s ON s.ord = m.ord WHERE s.user_id IS NULL);
  END IF;
END $$;

-- ── 3. Clean up a previous seed.
DELETE FROM "PlayerLineupSlot"
 WHERE "PlayerLineupId" IN (SELECT "Id" FROM "PlayerLineup" WHERE "PickemGroupId" = '5eed0005-0000-4000-8000-00000000a001');
DELETE FROM "PlayerLineup"      WHERE "PickemGroupId" = '5eed0005-0000-4000-8000-00000000a001';
DELETE FROM "PickemGroupWeek"   WHERE "GroupId"       = '5eed0005-0000-4000-8000-00000000a001';
DELETE FROM "PickemGroupMember" WHERE "PickemGroupId" = '5eed0005-0000-4000-8000-00000000a001';
DELETE FROM "PickemGroup"       WHERE "Id"            = '5eed0005-0000-4000-8000-00000000a001';

-- ── 4. League: clone an existing local NCAAFB Player Pick'em league
--    (GroupType 1 = PlayerPickem, Sport 2 = FootballNcaa) so every required
--    column is valid, then override identity and window.
CREATE TEMP TABLE seed_group ON COMMIT DROP AS
SELECT * FROM "PickemGroup"
 WHERE "GroupType" = 1 AND "Sport" = 2 AND "Id" <> '5eed0005-0000-4000-8000-00000000a001'
 ORDER BY "CreatedUtc" DESC
 LIMIT 1;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM seed_group) THEN
    RAISE EXCEPTION 'No local NCAAFB Player Pick''em league to clone; create one in the web app first.';
  END IF;
END $$;

UPDATE seed_group SET
  "Id" = '5eed0005-0000-4000-8000-00000000a001',
  "Name" = 'NCAA Wk5 PP (seed)',
  "Description" = 'Seeded week-5 Player Pick''em league (fake scores)',
  "CommissionerUserId" = (SELECT user_id FROM seed_user WHERE ord = 1),
  "CreatedBy" = (SELECT user_id FROM seed_user WHERE ord = 1),
  "CreatedUtc" = now(),
  "ModifiedBy" = NULL,
  "ModifiedUtc" = NULL,
  "SeasonYear" = 2026,
  "LeagueWindow" = 2,  -- DateRange
  "StartsOn" = '2026-09-29 00:00:00+00',
  "EndsOn" = '2026-10-05 23:59:59+00',
  "DeactivatedUtc" = NULL,
  "InvitationsExpireUtc" = NULL,
  "IsPublic" = false;

INSERT INTO "PickemGroup" SELECT * FROM seed_group;

-- ── 5. The league's week: NCAAFB 2026 regular-season week 5, taken from any
--    local NCAAFB league that already has it.
INSERT INTO "PickemGroupWeek"
  ("GroupId", "SeasonWeekId", "Id", "SeasonYear", "SeasonWeek", "SeasonPhaseTypeCode",
   "IsNonStandardWeek", "AreMatchupsGenerated", "CreatedBy", "CreatedUtc")
SELECT '5eed0005-0000-4000-8000-00000000a001', w."SeasonWeekId", gen_random_uuid(), 2026, 5, 2,
       false, true, (SELECT user_id FROM seed_user WHERE ord = 1), now()
FROM "PickemGroupWeek" w
JOIN "PickemGroup" g ON g."Id" = w."GroupId"
WHERE g."Sport" = 2 AND w."SeasonYear" = 2026 AND w."SeasonWeek" = 5 AND w."SeasonPhaseTypeCode" = 2
LIMIT 1;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "PickemGroupWeek" WHERE "GroupId" = '5eed0005-0000-4000-8000-00000000a001') THEN
    RAISE EXCEPTION 'No local NCAAFB league has a 2026 week-5 row to take the SeasonWeekId from.';
  END IF;
END $$;

-- ── 6. Members (ord 1 = Commissioner role 2, others Member role 0).
INSERT INTO "PickemGroupMember" ("Id", "PickemGroupId", "UserId", "Role", "CreatedBy", "CreatedUtc")
SELECT gen_random_uuid(), '5eed0005-0000-4000-8000-00000000a001', s.user_id, CASE WHEN s.ord = 1 THEN 2 ELSE 0 END,
       (SELECT user_id FROM seed_user WHERE ord = 1), now()
FROM seed_user s;

-- ── 7. Rosters: real week-5 athletes, fake points.
CREATE TEMP TABLE seed_slot (
  ord int, slot_id text, athlete_id uuid, athlete_season_id uuid, position text,
  first_name text, last_name text, team_name text, team_slug text,
  contest_id uuid, contest_start timestamptz, opponent_name text, points numeric, stat_line text
) ON COMMIT DROP;
