-- One lineup per member who has a roster.
INSERT INTO "PlayerLineup"
  ("Id", "PickemGroupId", "UserId", "SeasonYear", "SeasonWeek", "TotalPoints", "ScoreUpdatedUtc", "CreatedBy", "CreatedUtc")
SELECT gen_random_uuid(), '5eed0005-0000-4000-8000-00000000a001', s.user_id, 2026, 5,
       (SELECT sum(points) FROM seed_slot x WHERE x.ord = s.ord), now(), s.user_id, now()
FROM seed_user s
WHERE EXISTS (SELECT 1 FROM seed_slot x WHERE x.ord = s.ord);

INSERT INTO "PlayerLineupSlot"
  ("Id", "PlayerLineupId", "SlotId", "AthleteId", "AthleteSeasonId", "Position", "FirstName", "LastName",
   "TeamName", "TeamSlug", "ContestId", "ContestStartUtc", "OpponentName", "Points", "StatLine",
   "IsScoreFinal", "CreatedBy", "CreatedUtc")
SELECT gen_random_uuid(), l."Id", x.slot_id, x.athlete_id, x.athlete_season_id, x.position, x.first_name, x.last_name,
       x.team_name, x.team_slug, x.contest_id, x.contest_start, x.opponent_name, x.points, x.stat_line,
       true, s.user_id, now()
FROM seed_slot x
JOIN seed_user s ON s.ord = x.ord
JOIN "PlayerLineup" l ON l."PickemGroupId" = '5eed0005-0000-4000-8000-00000000a001' AND l."UserId" = s.user_id;

-- ── 8. What got seeded.
SELECT u."DisplayName", l."TotalPoints", count(ps."Id") AS slots
FROM "PlayerLineup" l
JOIN "User" u ON u."Id" = l."UserId"
LEFT JOIN "PlayerLineupSlot" ps ON ps."PlayerLineupId" = l."Id"
WHERE l."PickemGroupId" = '5eed0005-0000-4000-8000-00000000a001'
GROUP BY u."DisplayName", l."TotalPoints"
ORDER BY l."TotalPoints" DESC;

COMMIT;

